sp_ListarLancamentosCaixa	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_ListarLancamentosCaixa`(IN p_idCaixa INT)\nBEGIN\n\n    SELECT\n\n        lc.idLancamento,\n\n        lc.idCaixa,\n\n        lc.idEmpresa,\n\n        lc.idUsuario,\n\n        lc.idFormaPagamento,\n\n        fp.nome              AS nomeFormaPagamento,\n\n        lc.idCategoriaFinanceira,\n\n        cf.Nome              AS nomeCategoria,\n\n        cf.Tipo              AS tipoCategoria,\n\n        lc.valor,\n\n        lc.dthLancamento,\n\n        lc.descricao,\n\n        lc.referencia,\n\n        lc.tipoLancamento,\n\n        lc.pedido_id,\n\n        lc.cliente_id,\n\n        cl.nome              AS nomeCliente\n\n    FROM LancamentoCaixa lc\n\n    LEFT JOIN FormaPagamento      fp ON fp.idFormaPagamento       = lc.idFormaPagamento\n\n    LEFT JOIN CategoriaFinanceira cf ON cf.idCategoriaFinanceira  = lc.idCategoriaFinanceira\n\n    LEFT JOIN Cliente             cl ON cl.idCliente              = lc.cliente_id\n\n    WHERE lc.idCaixa = p_idCaixa\n\n    ORDER BY lc.dthLancamento DESC;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
